public class Main {
    public static void main(String[] args) {
        SimpleHashMap ages = new SimpleHashMap();
        ages.put(3, "Ana is 21");
        ages.put(7, "Ben is 19"); // 7 % 4 == 3, same bucket as 3
        ages.put(2, "Cy is 30");
        System.out.println(ages.get(7));
        System.out.println(ages.get(2));
        System.out.println(ages.get(5));
    }
}

class Entry {
    int key;
    String value;
    Entry next;

    Entry(int key, String value) {
        this.key = key;
        this.value = value;
    }
}

class SimpleHashMap {
    Entry[] buckets = new Entry[4];

    int bucketFor(int key) {
        return key % buckets.length;
    }

    void put(int key, String value) {
        int b = bucketFor(key);
        for (Entry e = buckets[b]; e != null; e = e.next) {
            if (e.key == key) {
                e.value = value; // key already there: replace the value
                return;
            }
        }
        Entry entry = new Entry(key, value);
        entry.next = buckets[b]; // put it at the front of this bucket's chain
        buckets[b] = entry;
    }

    String get(int key) {
        for (Entry e = buckets[bucketFor(key)]; e != null; e = e.next) {
            if (e.key == key) return e.value;
        }
        return "not found";
    }
}
